import {learningMap} from './data/learning-map-data.js';

export function getLearningConnections(id, edges=learningMap.dependencies) {
 const walk=(backwards)=>{const found=new Set(),queue=[id];while(queue.length){const current=queue.shift();for(const e of edges){const from=backwards?e.topicId:e.prerequisiteId,to=backwards?e.prerequisiteId:e.topicId;if(from===current&&to!==id&&!found.has(to)){found.add(to);queue.push(to);}}}return found;};
 return {before:walk(true),after:walk(false),directBefore:edges.filter(e=>e.topicId===id),directAfter:edges.filter(e=>e.prerequisiteId===id)};
}

export function initLearningMap({openActivity,lang="zh",caseForSkill}) {
 const mount=document.getElementById('learningMap');if(!mount)return;
 const t=(en,zh)=>lang==="en"?en:zh, nodeLabel=n=>lang==="en"?n.name:n.zh;
 const nodes=learningMap.topics.map(n=>({...n,activity:caseForSkill?.(n.id)||n.activity})),edges=learningMap.dependencies;
 const byId=new Map([...nodes,...learningMap.externalTopics].map(n=>[n.id,n]));
 const internal=edges.filter(e=>nodes.some(n=>n.id===e.prerequisiteId));
 const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 let selected='mt_6eTZUwKQZr',focusOnly=false;
 const positions=new Map(),counts={};
 for(const n of nodes){const col=n.ageRangeStart-5,row=counts[col]||0;counts[col]=row+1;positions.set(n.id,{x:20+col*192,y:75+row*118});}
 mount.innerHTML=`<div class="map-heading"><div><p class="eyebrow">MARBLE · LEARNING TO LEARN</p><h2>${t("Learning to Learn \u00b7 Skill map","学会学习 · 能力地图")}</h2><p>${t("Select one of 18 skills to explore its connections.","18个知识点，点一个看看它和其他能力怎样相连。")}</p></div><a href="https://withmarble.com/curriculum/" target="_blank" rel="noopener">${t("Original map \u2197","查看原版地图 ↗")}</a></div><div class="map-controls"><label><input id="mapFocus" type="checkbox">${t("Show only this skill\u2019s learning paths","只显示所选能力的前后路径")}</label><span class="map-legend"><i class="line-key"></i>${t("Required (hard)","必要前置（hard）")}<i class="line-key soft"></i>${t("Helpful (soft)","有帮助的基础（soft）")}</span></div><p class="map-hint">${t("Arrows lead from foundations to later skills. Ages are references, not deadlines. Scroll horizontally or use the picker.","箭头从基础能力指向后续能力；参考年龄不是达标期限。左右滑动看全图，或用下方选择框定位。")}</p><label class="map-picker-label" for="mapPicker">${t("Choose a skill ","选择能力 ")}<select id="mapPicker">${nodes.map(n=>`<option value="${n.id}">${nodeLabel(n)} · ${n.ageRangeStart}—${n.ageRangeEnd}${t(" years","岁")}</option>`).join('')}</select></label><div class="map-layout"><div class="map-scroll" tabindex="0" role="region" aria-label="${t("Skill map, scroll horizontally","知识地图，可左右滚动")}"><div class="map-canvas"><svg class="map-lines" viewBox="0 0 1160 555" aria-hidden="true"><defs><marker id="mapArrow" markerWidth="7" markerHeight="7" refX="6" refY="3.5" orient="auto"><path d="M0,0 L7,3.5 L0,7" fill="#789771"/></marker></defs><g id="mapEdges"></g></svg>${[5,6,7,8,9,10].map((age,i)=>`<span class="map-age-band" style="left:${20+i*192}px">${age}—${age+1}${t(" years","岁")}<span>${t("Source reference age","原始参考年龄")}</span></span>`).join('')}<div id="mapNodes">${nodes.map(n=>{const p=positions.get(n.id);return `<button type="button" class="map-node" data-map-node="${n.id}" style="left:${p.x}px;top:${p.y}px"><strong>${nodeLabel(n)}</strong><span>${n.activity?t("Activity available","可打开亲子练习"):t("Explore connections","查看说明与关系")}</span></button>`;}).join('')}</div></div></div><div id="mapDetail" class="map-detail" aria-live="polite"></div></div><p class="map-footnote">${t("22 original internal links are shown. Three mathematics prerequisites appear in the relevant details. Layout and translations are adapted; links do not indicate mastery.","图中保留 Marble 原始的22条学科内部关系；3条来自数学学科的前置关系列在对应节点详情中。中文说明与布局由本站改编，连线不表示孩子已经掌握。")}</p>`;
 const detail=mount.querySelector('#mapDetail'),picker=mount.querySelector('#mapPicker');
 function selectNode(id,{pan=false}={}){if(!positions.has(id))return false;selected=id;render();if(pan){const p=positions.get(id),scroller=mount.querySelector('.map-scroll');scroller.scrollTo({left:Math.max(0,p.x-scroller.clientWidth/2+82),behavior:'auto'});}return true;}
 function render(){const node=byId.get(selected),c=getLearningConnections(selected),related=new Set([selected,...c.before,...c.after]);picker.value=selected;
 for(const button of mount.querySelectorAll('[data-map-node]')){const id=button.dataset.mapNode;button.classList.toggle('selected',id===selected);button.classList.toggle('before',c.before.has(id));button.classList.toggle('after',c.after.has(id));button.hidden=focusOnly&&!related.has(id);button.setAttribute('aria-pressed',String(id===selected));}
 const pathIds=new Set([selected,...c.before,...c.after]);
 mount.querySelector('#mapEdges').innerHTML=internal.map(e=>{const from=positions.get(e.prerequisiteId),to=positions.get(e.topicId),onPath=pathIds.has(e.prerequisiteId)&&pathIds.has(e.topicId),direct=e.topicId===selected||e.prerequisiteId===selected;if(focusOnly&&!onPath)return '';let d;if(from.x===to.x){const side=from.x+177;d=`M ${from.x+164} ${from.y+35} C ${side+8} ${from.y+35}, ${side+8} ${to.y+35}, ${to.x+164} ${to.y+35}`;}else if(to.x-from.x>192){const sx=from.x+164,sy=from.y+35,ex=to.x,ey=to.y+35,lane=530+(e.sourceLine%4)*6;d=`M ${sx} ${sy} C ${sx+13} ${sy}, ${sx+13} ${sy}, ${sx+13} ${sy+12} L ${sx+13} ${lane-8} Q ${sx+13} ${lane}, ${sx+21} ${lane} L ${ex-20} ${lane} Q ${ex-12} ${lane}, ${ex-12} ${lane-8} L ${ex-12} ${ey+12} Q ${ex-12} ${ey}, ${ex} ${ey}`;}else{const start=from.x+164,end=to.x,mid=(start+end)/2;d=`M ${start} ${from.y+35} C ${mid} ${from.y+35}, ${mid} ${to.y+35}, ${end} ${to.y+35}`;}return `<path d="${d}" fill="none" stroke="${direct?'#b2e889':onPath?'#789771':'#334638'}" stroke-width="${direct?2.4:1.5}" ${e.strength==='soft'?'stroke-dasharray="5 4"':''} marker-end="url(#mapArrow)"/>`;}).join('');
 const relations=(list,before)=>list.length?`<ul>${list.map(e=>{const n=byId.get(before?e.prerequisiteId:e.topicId),local=positions.has(n.id),label=local?`<button type="button" data-map-link="${n.id}">${esc(nodeLabel(n))}</button>`:`<a href="https://github.com/withmarbleapp/os-taxonomy/blob/main/data/topics.json#L${n.sourceLine}" target="_blank" rel="noopener">${esc(nodeLabel(n))} ↗</a><span class="external-subject">${t("Mathematics","数学学科")}</span>`;return `<li>${label}<span class="relation-strength">${e.strength==='hard'?t("Required foundation","必要前置"):t("Helpful foundation","辅助基础")}</span><p>${esc(t(e.reason,e.reasonZh))}</p><a class="edge-source" href="https://github.com/withmarbleapp/os-taxonomy/blob/main/data/dependencies.json#L${e.sourceLine}" target="_blank" rel="noopener">${t("Original relationship \u2197","原始连线依据 ↗")}</a></li>`;}).join('')}</ul>`:`<p class="map-empty">${before?t("No prerequisites are listed for this skill in the source.","原数据未列出该能力的前置要求。"):t("No direct next skill in this subject. Other subjects may have connections.","本学科没有列出直接后续节点；不表示其他学科没有关联。")}</p>`;
 detail.innerHTML=`<span class="pill">${t("Selected \u00b7 ","当前选中 · ")}${node.ageRangeStart}—${node.ageRangeEnd}${t(" years","岁")}</span><h3>${esc(nodeLabel(node))}</h3><p class="map-english">${lang==="en"?esc(node.id):esc(node.name)}</p><p>${esc(t(node.descriptionEn,node.description))}</p><div class="map-prompt"><strong>${t("A question to explore","和孩子这样聊")}</strong><p>“${esc(t(node.promptEn,node.prompt))}”</p></div>${node.activity?`<button type="button" class="primary map-practice" data-map-practice="${node.activity}">${t("Open family activity \u2192","打开对应亲子练习 →")}</button>`:`<p class="map-empty">${t("Explore this with the question above.","先用上面的提问聊一聊。")}</p>`}<h4>${t("Foundations to build on","先有这些基础")}</h4>${relations(c.directBefore,true)}<h4>${t("What this can lead to","接下来可以发展")}</h4>${relations(c.directAfter,false)}<p class="map-source-note">${t("Bright green marks the selection; darker greens show earlier and later paths. Relationships are from Marble; family questions are adapted.","亮绿色为选中节点；深绿为前置路径，青绿为后续路径。关系取自 Marble，亲子提问由本站改写。")}</p><a href="https://github.com/withmarbleapp/os-taxonomy/blob/main/data/topics.json#L${node.sourceLine}" target="_blank" rel="noopener">${t("Original skill \u2197","查看原始知识点 ↗")}</a>`;
 detail.querySelectorAll('[data-map-link]').forEach(b=>b.addEventListener('click',()=>selectNode(b.dataset.mapLink,{pan:true})));
 detail.querySelector('[data-map-practice]')?.addEventListener('click',e=>{openActivity(e.currentTarget.dataset.mapPractice);const target=document.getElementById('practiceForm')||document.getElementById('activity');if(!target)return;target.setAttribute('tabindex','-1');target.scrollIntoView({block:'start',behavior:'auto'});target.focus({preventScroll:true});});
 }
 mount.querySelectorAll('[data-map-node]').forEach(b=>b.addEventListener('click',()=>selectNode(b.dataset.mapNode)));
 picker.addEventListener('change',()=>selectNode(picker.value,{pan:true}));
 mount.querySelector('#mapFocus').addEventListener('change',e=>{focusOnly=e.target.checked;render();});
 render();
 return {selectNode,getSelected:()=>selected};
}
